custom_css:
/* ==========================================================
   MoodTube theme: Crystal Handheld  (theme format v2)
   Translucent aqua handheld console.
   Two layouts, chosen by the player size (container query):
   - "device": portrait console with a LCD, a D-pad cross, a round
     cover button and a volume pill (absolute, fixed geometry);
   - "flow": any other size (wide or small) - a compact bar with
     round buttons, a mini LCD for the title and a dotted progress line.
   ========================================================== */

@import url('https://fonts.googleapis.com/css2?family=Pixelify+Sans:wght@400..700&display=swap');

@keyframes gb-spin { to { transform: rotate(360deg); } }
@keyframes gb-blink { 50% { opacity: 0.35; } }

/* ---------- Palette ---------- */
.mt-player, #mt-settings-modal, .mt-fab, .mt-pl-modal {
    --gb-ink:    #5f66b0;
    --gb-dim:    #8a92c8;
    --gb-lav:    #a79de2;
    --gb-lav-d:  #7d73c9;
    --gb-lav-l:  #dcd7f8;
    --gb-screen: #cdeeee;
    --gb-bezel:  #14203a;
    --gb-aqua:   #d9f3fa;
    --gb-aqua-d: #8ecbe0;
    --mt-text: #3f4a8c;
    --mt-text-dim: #7d86bd;
    --mt-text-on-accent: #ffffff;
}

/* ---------- Sliders ---------- */
.mt-progress {
    --mt-slider-track: repeating-linear-gradient(90deg, #8d93cf 0 2px, transparent 2px 5px);
    --mt-slider-track-height: 2px;
    --mt-slider-track-radius: 0;
    --mt-slider-thumb-size: 18px;
    --mt-slider-thumb-bg: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2016%2016%27%3E%3Cpath%20fill%3D%27%235f66b0%27%20d%3D%27M8%200.5L9.7%206.3L15.5%208L9.7%209.7L8%2015.5L6.3%209.7L0.5%208L6.3%206.3Z%27%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
    --mt-slider-thumb-bg-hover: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2016%2016%27%3E%3Cpath%20fill%3D%27%235f66b0%27%20d%3D%27M8%200.5L9.7%206.3L15.5%208L9.7%209.7L8%2015.5L6.3%209.7L0.5%208L6.3%206.3Z%27%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
    --mt-slider-thumb-border: none;
    --mt-slider-thumb-radius: 0;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--gb-ink);
}
.mt-volume {
    --mt-slider-track: rgba(255, 255, 255, 0.55);
    --mt-slider-track-height: 8px;
    --mt-slider-track-radius: 4px;
    --mt-slider-thumb-size: 18px;
    --mt-slider-thumb-bg: linear-gradient(#cfc8f6, var(--gb-lav));
    --mt-slider-thumb-bg-hover: linear-gradient(#ddd8fa, #b5acea);
    --mt-slider-thumb-border: 2px solid var(--gb-lav-d);
    --mt-slider-thumb-radius: 50%;
    --mt-slider-thumb-shadow: none;
    --mt-slider-progress: var(--gb-lav-d);
}

/* ---------- Shell (all sizes) ---------- */
.mt-player {
    container-type: size;
    padding: 34px 14px 14px;
    background: linear-gradient(160deg, rgba(150, 226, 242, 0.88), rgba(104, 188, 226, 0.84));
    border: 3px solid rgba(226, 248, 255, 0.95);
    border-radius: 30px;
    color: var(--gb-ink);
    font-family: 'Pixelify Sans', 'Courier New', monospace;
    box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.25);
    backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
}
.mt-player * { font-family: inherit; }
.mt-player i { font-family: 'Font Awesome 6 Free', 'Font Awesome 5 Free', FontAwesome; }

/* screws in the four corners */
.mt-player::before {
    content: ''; position: absolute; inset: 0; z-index: 1; pointer-events: none;
    background:
        radial-gradient(circle at 17px 17px, #e8ecfb 0 2.4px, #8a97cf 2.4px 3.8px, transparent 4.2px),
        radial-gradient(circle at calc(100% - 17px) 17px, #e8ecfb 0 2.4px, #8a97cf 2.4px 3.8px, transparent 4.2px),
        radial-gradient(circle at 17px calc(100% - 17px), #e8ecfb 0 2.4px, #8a97cf 2.4px 3.8px, transparent 4.2px),
        radial-gradient(circle at calc(100% - 17px) calc(100% - 17px), #e8ecfb 0 2.4px, #8a97cf 2.4px 3.8px, transparent 4.2px);
}
/* top plate with the label */
.mt-player::after {
    content: ''; position: absolute; z-index: 1; top: 8px; left: 50%; width: 96px; height: 20px; margin-left: -48px;
    box-sizing: border-box; border: 2px solid rgba(154, 144, 220, 0.9); border-radius: 7px;
    background: rgba(196, 190, 244, 0.65); pointer-events: none;
}
.mt-player-header { display: contents; }
.mt-player-header-title {
    position: absolute; z-index: 6; top: 10px; left: 50%; transform: translateX(-50%);
    color: var(--gb-ink); font-size: 11px; font-weight: 500; letter-spacing: 0.1em; text-transform: uppercase; white-space: nowrap;
}
.mt-player-status { display: none; }

.mt-window-btn {
    top: 8px; width: 20px; height: 20px; box-sizing: border-box;
    display: flex; align-items: center; justify-content: center;
    font-size: 9px; color: #ffffff;
    background: linear-gradient(#bdb4ee, var(--gb-lav)); border: 2px solid var(--gb-lav-d); border-radius: 50%;
}
.mt-btn-search   { right: auto; left: calc(50% - 100px); }
.mt-btn-settings { right: auto; left: calc(50% - 76px); }
.mt-btn-close    { right: calc(50% - 76px); }
.mt-resize-handle i { opacity: 0; } /* the bottom-right screw marks the resize corner */

/* ---------- Flow layout (wide / small sizes) ---------- */
.mt-player .mt-player-body { gap: 10px; }

.mt-cover {
    width: 54px; height: 54px; box-sizing: border-box; padding: 0; box-shadow: none;
    border: 3px solid var(--gb-lav-d); border-radius: 50%; background: var(--gb-lav);
}
.mt-cover-img { width: 100%; height: 100%; border-radius: 50%; background: var(--gb-lav); }
.mt-cover-hole { display: none; }
.mt-player.mt-is-playing .mt-cover-img { animation: gb-spin 8s linear infinite; }

/* the title lives in a mini LCD */
.mt-player .mt-player-body .mt-track-info {
    background: var(--gb-screen); border: 4px solid var(--gb-bezel); border-radius: 11px; box-sizing: border-box;
    padding: 3px 26px 3px 10px; box-shadow: inset 0 0 0 2px #7f8bd0;
}
.mt-track-title { color: var(--gb-ink); font-size: 15px; font-weight: 500; margin-bottom: 0; }
.mt-track-subtitle { color: var(--gb-dim); font-size: 10px; font-weight: 400; }
.mt-btn-favorite { color: var(--gb-ink); font-size: 11px; right: 8px; top: 7px; }

.mt-time { color: var(--gb-dim); font-size: 10px; }

.mt-controls { gap: 8px; }
.mt-controls > .mt-btn {
    width: 32px; height: 32px; box-sizing: border-box; display: flex; align-items: center; justify-content: center;
    font-size: 11px; color: #ffffff;
    background: linear-gradient(#b9afee, var(--gb-lav)); border: 2px solid var(--gb-lav-d); border-radius: 50%;
}
.mt-controls > .mt-btn-play { width: 36px; height: 36px; font-size: 13px; background: linear-gradient(#a79de2, #8e83d6); }
.mt-controls > .mt-btn:hover { transform: none; background: linear-gradient(#cbc3f4, #b3a9ec); color: #ffffff; }
.mt-controls > .mt-btn:active { background: var(--gb-lav-d); }
.mt-btn-ai.mt-is-busy { color: #fff7a8; }

.mt-volume-icon { color: var(--gb-lav-d); font-size: 11px; }

/* wide bar: tighter parts so everything fits next to each other */
.mt-player.moodtube-row-layout .mt-player-body { gap: 8px; }
.mt-player.moodtube-row-layout .mt-cover { width: 46px; height: 46px; border-width: 2px; }
.mt-player.moodtube-row-layout .mt-player-body .mt-track-info { flex: 1 1 130px; min-width: 70px; padding: 2px 22px 2px 8px; }
.mt-player.moodtube-row-layout .mt-track-title { font-size: 13px; }
.mt-player.moodtube-row-layout .mt-progress { flex: 1 1 90px; min-width: 70px; }
.mt-player.moodtube-row-layout .mt-controls { gap: 5px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn { width: 28px; height: 28px; font-size: 10px; }
.mt-player.moodtube-row-layout .mt-controls > .mt-btn-play { width: 32px; height: 32px; font-size: 12px; }
.mt-player.moodtube-row-layout .mt-volume { flex: 0 1 90px; min-width: 60px; }

/* narrow window: five round buttons still fit in one row */
@container (max-width: 200px) {
    .mt-player .mt-controls { gap: 3px; }
    .mt-player .mt-controls > .mt-btn { width: 26px; height: 26px; font-size: 9px; }
    .mt-player .mt-controls > .mt-btn-play { width: 30px; height: 30px; font-size: 11px; }
}

/* ---------- Device layout (portrait console), only when the player is big enough ---------- */
@container (min-width: 214px) and (min-height: 294px) {
    .mt-player:not(.moodtube-row-layout) .mt-player-body { display: block; position: relative; height: 296px; }

    /* LCD: bezel border + pale screen, dotted line on the top edge */
    .mt-player:not(.moodtube-row-layout) .mt-player-body::before {
        content: ''; position: absolute; left: 0; top: 0; width: 100%; height: 156px; box-sizing: border-box;
        border: 7px solid var(--gb-bezel); border-radius: 16px; box-shadow: inset 0 0 0 2px #7f8bd0;
        background:
            repeating-linear-gradient(90deg, #8d93cf 0 2px, transparent 2px 5px) 34px 10px / calc(100% - 82px) 2px no-repeat,
            var(--gb-screen);
    }

    /* title, subtitle, favourite heart on the screen */
    .mt-player:not(.moodtube-row-layout) .mt-player-body .mt-track-info {
        position: absolute; left: 7px; top: 26px; width: calc(100% - 14px); height: 66px; box-sizing: border-box;
        padding: 0 20px; align-items: center; justify-content: center; text-align: center;
        background: none; border: none; border-radius: 0; box-shadow: none;
    }
    .mt-player:not(.moodtube-row-layout) .mt-track-info > .mt-track-title {
        display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; white-space: normal;
        font-size: 19px; line-height: 1.1; margin: 0; text-align: center;
    }
    .mt-player:not(.moodtube-row-layout) .mt-track-subtitle { margin-top: 3px; }
    .mt-player:not(.moodtube-row-layout) .mt-btn-favorite { left: 8px; right: auto; top: -10px; }

    /* status pill (PLAY / PAUSE / ...) under the title */
    .mt-player:not(.moodtube-row-layout) .mt-player-status {
        display: block; position: absolute; z-index: 3; top: 128px; left: 50%; transform: translateX(-50%);
        padding: 0 10px; border: 2px solid #8d93cf; border-radius: 7px; color: var(--gb-ink); opacity: 1;
        font-size: 11px; font-weight: 500; letter-spacing: 0.08em; white-space: nowrap;
    }
    .mt-player.mt-is-playing:not(.moodtube-row-layout) .mt-player-status { animation: gb-blink 1.6s steps(2, jump-none) infinite; }

    /* progress: dotted line with a sparkle, timers under it */
    .mt-player:not(.moodtube-row-layout) .mt-progress { position: absolute; left: 18px; right: 18px; top: 116px; width: auto; height: 18px; margin: 0; }
    .mt-player:not(.moodtube-row-layout) .mt-time { position: absolute; top: 20px; min-width: 0; }
    .mt-player:not(.moodtube-row-layout) .mt-time-current { left: 0; }
    .mt-player:not(.moodtube-row-layout) .mt-time-total { right: 0; }

    /* D-pad: queue / prev / play / next / AI as one solid cross (no seams) */
    .mt-player:not(.moodtube-row-layout) .mt-controls {
        position: absolute; left: 8px; top: 166px; display: grid;
        grid-template-columns: repeat(3, 32px); grid-template-rows: repeat(3, 32px); gap: 0;
    }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn { background: var(--gb-lav); border-radius: 0; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn-queue { grid-area: 1 / 2; border-radius: 9px 9px 0 0; border-bottom: none; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn-prev  { grid-area: 2 / 1; border-radius: 9px 0 0 9px; border-right: none; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn-next  { grid-area: 2 / 3; border-radius: 0 9px 9px 0; border-left: none; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn-ai    { grid-area: 3 / 2; border-radius: 0 0 9px 9px; border-top: none; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn-play  {
        grid-area: 2 / 2; width: 32px; height: 32px; font-size: 13px; border: none;
        background: radial-gradient(circle at 50% 50%, #8e83d6 0 12px, transparent 12.5px), var(--gb-lav);
    }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn:hover { background: #b7aeea; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn-play:hover { background: radial-gradient(circle at 50% 50%, #7d72cc 0 12px, transparent 12.5px), #b7aeea; }
    .mt-player:not(.moodtube-row-layout) .mt-controls > .mt-btn:active { background: #8e83d6; }
    /* speaker grille */
    .mt-player:not(.moodtube-row-layout) .mt-controls::after {
        content: ''; position: absolute; left: 112px; top: 48px; width: 26px; height: 26px; opacity: 0.8;
        background: radial-gradient(circle, #5a86c8 1.3px, transparent 1.7px) 0 0 / 6px 6px;
    }

    /* cover = the round "A" button, level with the cross */
    .mt-player:not(.moodtube-row-layout) .mt-cover {
        position: absolute; right: 10px; top: 178px; width: 72px; height: 72px;
    }

    /* volume: pill like the SELECT / START buttons */
    .mt-player:not(.moodtube-row-layout) .mt-volume { position: absolute; left: 0; top: 268px; width: 100%; padding: 0 6px; box-sizing: border-box; }
}

/* ---------- Queue / playlists ---------- */
.mt-panel { background: var(--gb-aqua); padding-top: 40px; border-radius: 24px; }
.mt-panel-title { color: var(--gb-ink); font-size: 11px; }
.mt-panel-close, .mt-panel .mt-btn-accent { color: var(--gb-lav-d); }
.mt-queue-item { background: #eefbfe; border-color: var(--gb-aqua-d); border-radius: 8px; }
.mt-queue-item:hover { background: #ffffff; }
.mt-queue-item.mt-is-current { background: #ffffff; border-color: var(--gb-lav-d); }
.mt-queue-thumb { border-radius: 6px; }
.mt-queue-thumb.mt-is-empty { background: var(--gb-lav-l); }
.mt-queue-title, .mt-queue-item.mt-is-current .mt-queue-title, .mt-playlist-title { color: var(--gb-ink); }
.mt-queue-item.mt-is-blocked .mt-queue-title { color: #c0405e; }
.mt-queue-now, .mt-queue-add { color: var(--gb-lav-d); }
.mt-queue-dislike { background-color: var(--gb-lav-d); }
.mt-queue-empty { color: var(--gb-dim); }

/* ---------- Floating button ---------- */
.mt-fab, .mt-fab.mt-fab-docked {
    background: linear-gradient(#bdb4ee, var(--gb-lav)); border-color: var(--gb-lav-d);
    box-shadow: none; color: #ffffff;
}

/* ---------- Scrollbars ---------- */
.mt-player *, #mt-settings-modal * { scrollbar-width: thin; scrollbar-color: var(--gb-lav) transparent; }
.mt-player ::-webkit-scrollbar, #mt-settings-modal ::-webkit-scrollbar { width: 8px; height: 8px; }
.mt-player ::-webkit-scrollbar-track, #mt-settings-modal ::-webkit-scrollbar-track { background: rgba(255, 255, 255, 0.4); border-radius: 4px; }
.mt-player ::-webkit-scrollbar-thumb, #mt-settings-modal ::-webkit-scrollbar-thumb { background: var(--gb-lav); border-radius: 4px; }

/* ---------- Settings window ---------- */
#mt-settings-modal, #mt-settings-modal * { text-shadow: none; }
#mt-settings-modal {
    --mt-overlay: rgba(20, 40, 80, 0.4);
    --mt-modal-shadow: none;
    --mt-text-strong: var(--gb-ink);
    --mt-divider: rgba(142, 203, 224, 0.6);
}
#mt-settings-modal .mt-flex-container { border: 3px solid rgba(226, 248, 255, 0.95); border-radius: 26px; backdrop-filter: none; }
#mt-settings-modal .mt-close { color: var(--gb-lav-d); }
#mt-settings-modal .mt-content { scrollbar-color: var(--gb-lav) transparent; }
#mt-settings-modal .mt-cat-title:hover { background-color: rgba(167, 157, 226, 0.12); }
#mt-settings-modal .mt-tag { background-color: #eefbfe; border-color: var(--gb-aqua-d); box-shadow: none; }
#mt-settings-modal .mt-genre-tag:hover, #mt-settings-modal .mt-mood-tag:hover, #mt-settings-modal .mt-scenario-tag:hover {
    background-color: #ffffff; border-color: var(--gb-lav-d);
}
#mt-settings-modal .mt-genre-tag.active, #mt-settings-modal .mt-mood-tag.active, #mt-settings-modal .mt-scenario-tag.active {
    background-color: var(--gb-lav-d); border-color: var(--gb-lav-d); box-shadow: none;
}
#mt-settings-modal .mt-sum-genre, #mt-settings-modal .mt-sum-mood, #mt-settings-modal .mt-sum-scenario { box-shadow: none; }
#mt-settings-modal .mt-btn-test { background: #eefbfe; border-color: var(--gb-aqua-d); }
#mt-settings-modal .mt-btn-test:hover { background: #ffffff; border-color: var(--gb-lav-d); }
#mt-settings-modal .mt-subpanel { background: #eefbfe; }

/* ---------- Search panel and playlists (added to the extension later) ---------- */

.mt-panel-search { --mt-bg-primary: #d9f3fa; }
#moodtube-search-container #moodtube-search-go { color: var(--mt-text-on-accent, #fff) !important; }
.mt-player, .mt-pl-modal { --mt-pl-spotify-tab: var(--gb-lav-d); --mt-pl-spotify-tab-text: #ffffff; }
.mt-btn-favorite.mt-is-active { color: var(--gb-lav-d); }
.mt-pl-tabs { background: rgba(255, 255, 255, 0.55); }
.mt-pl-tab { color: var(--gb-dim); }
.mt-pl-tool { background: #eefbfe; border-color: var(--gb-aqua-d); color: var(--gb-ink); }
.mt-pl-tool:hover { background: #ffffff; }
.mt-pl-tool.mt-pl-play { background: var(--gb-lav-d); border-color: var(--gb-lav-d); color: #ffffff; }
.mt-pl-inline-cancel { background: #eefbfe; color: var(--gb-ink); }
.mt-pl-cover-empty { background: var(--gb-lav-l); color: var(--gb-lav-d); }
.mt-pl-modal { --mt-overlay: rgba(20, 40, 80, 0.4); }
.mt-pl-modal-box { background: var(--gb-aqua); border: 3px solid rgba(226, 248, 255, 0.95); border-radius: 24px; box-shadow: none; }
.mt-pl-modal-track { border-bottom-color: var(--gb-aqua-d); }
.mt-pl-modal-close { color: var(--gb-lav-d); }
.mt-pl-option { background: #eefbfe; }
.mt-pl-option:hover { background: #ffffff; }
.mt-pl-option.mt-is-added .mt-pl-option-icon { color: var(--gb-lav-d); }

/* ---------- Theme catalog in the settings window ---------- */
#mt-settings-modal .mt-catalog-preview { background: var(--gb-lav-l); color: var(--gb-lav-d); }
#mt-settings-modal .mt-catalog-tag { background: var(--gb-lav-l); color: var(--gb-ink); }

/* ===== Dock bar (strip under the tavern header) [auto] ===== */
#moodtube-dock {
  font-family: 'Pixelify Sans', 'Courier New', monospace;
  --mt-dock-cover-radius: 4px;
}
#moodtube-dock, #moodtube-dock * { text-shadow: none; }
#moodtube-dock .mt-dock-cover { border-width: 1.5px; }
#moodtube-dock .mt-dock-controls { gap: 6px; }
#moodtube-dock .mt-dock-btn {
  width: 28px; height: 28px; padding: 0; box-sizing: border-box; line-height: 1; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center; border-radius: 4px;
  font-size: 12px; color: var(--mt-text);
  background: color-mix(in srgb, var(--mt-accent) 12%, transparent);
  transform: none; transition: background-color 0.2s;
}
#moodtube-dock .mt-dock-btn:hover { transform: none; color: var(--mt-text); background: color-mix(in srgb, var(--mt-accent) 28%, transparent); }
#moodtube-dock .mt-dock-play {
  width: 34px; height: 34px; font-size: 14px;
  background: var(--mt-accent); color: var(--mt-text-on-accent, #ffffff);
}
#moodtube-dock .mt-dock-play:hover { background: var(--mt-accent-hover, var(--mt-accent)); color: var(--mt-text-on-accent, #ffffff); }
#moodtube-dock .mt-dock-play.fa-play { padding-left: 2px; }
#moodtube-dock .mt-dock-fav, #moodtube-dock .mt-dock-ai, #moodtube-dock .mt-dock-queue { color: var(--mt-text); }
#moodtube-dock .mt-dock-fav.mt-is-active, #moodtube-dock .mt-dock-ai.mt-is-busy { color: var(--mt-accent); }
#moodtube-dock .mt-dock-expand, #moodtube-dock .mt-dock-close { color: var(--mt-text-dim, var(--mt-text)); }
#moodtube-dock .mt-dock-queue.mt-is-open, #moodtube-dock .mt-dock-expand.mt-is-open {
  color: var(--mt-text); text-shadow: none; background: color-mix(in srgb, var(--mt-accent) 30%, transparent);
}
#moodtube-dock .mt-dock-progress { height: 3px; }
@media (max-width: 420px) {
  #moodtube-dock .mt-dock-inner { gap: 6px; padding-left: 8px; padding-right: 8px; }
  #moodtube-dock .mt-dock-controls { gap: 3px; }
  #moodtube-dock .mt-dock-btn { width: 24px; height: 24px; font-size: 11px; }
  #moodtube-dock .mt-dock-play { width: 28px; height: 28px; font-size: 12px; }
}
/* ===== /Dock bar ===== */
/* == lyrics button == the fourth window button, in line with search / settings / close */
.mt-player .mt-window-btn.mt-btn-lyrics { right: auto; left: calc(50% - 124px); }
.mt-player .mt-lyrics-body { scrollbar-width: none; }
.mt-player .mt-lyrics-body::-webkit-scrollbar { display: none; width: 0; }
/* == /lyrics == */
/* == window buttons == 28px touch targets, evenly spaced, in line with the header */
#moodtube-mini-player .mt-window-btn { width: 26px; height: 26px; top: 7px; font-size: 13px; }
#moodtube-mini-player .mt-window-btn.mt-btn-search { right: auto; left: calc(50% - 112px); }
